using Mbb.Archive.Modules.Archive.Application;
using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.Modules.Archive.Application.Abstractions;using Mbb.Archive.Modules.Archive.Domain.Records;
namespace Mbb.Archive.Modules.Archive.Application.Records.RegisterCandidate;
public sealed class RegisterArchiveCandidateCommandHandler:ICommandHandler<RegisterArchiveCandidateCommand,Guid>{private readonly IArchiveRecordRepository _records;private readonly IInbox<ArchiveBoundary> _inbox;private readonly IUnitOfWork<ArchiveBoundary> _uow;public RegisterArchiveCandidateCommandHandler(IArchiveRecordRepository records,IInbox<ArchiveBoundary> inbox,IUnitOfWork<ArchiveBoundary> uow){_records=records;_inbox=inbox;_uow=uow;}public async Task<Result<Guid>> Handle(RegisterArchiveCandidateCommand command,CancellationToken ct){if(await _inbox.HasProcessedAsync(command.MessageId,ct))return Result<Guid>.Failure(Error.Conflict("archive.message_processed","Archive source event was already processed."));var existing=await _records.GetByDocumentVersionAsync(command.DocumentVersionId,ct);if(existing is not null){_inbox.MarkProcessed(command.MessageId,command.EventName,command.OccurredAt);await _uow.SaveChangesAsync(ct);return Result<Guid>.Success(existing.Id.Value);}var record=ArchiveRecord.RegisterCandidate(command.DocumentId,command.DocumentVersionId,command.OriginalStorageKey,command.Sha256Hash,command.MimeType,command.SizeBytes,command.OccurredAt);await _records.AddAsync(record,ct);_inbox.MarkProcessed(command.MessageId,command.EventName,command.OccurredAt);await _uow.SaveChangesAsync(ct);return Result<Guid>.Success(record.Id.Value);}}
